MATCH (m1:AircraftModel {name: "Douglas A-26 Invader"}), (m2:AircraftModel {name: "Junkers Ju 52"})
RETURN CASE WHEN toFloat(m1.height_metre) > toFloat(m2.height_metre) THEN m1.name ELSE m2.name END AS tallerModel,
       CASE WHEN toFloat(m1.height_metre) > toFloat(m2.height_metre) THEN m1.height_metre ELSE m2.height_metre END AS height_metre;

MATCH (fa:FlightAccident)-[:operatedBy]->(op:Operator), (fa)-[:departsFrom]->(ap:Airport)
WHERE op.name = "Air New Zealand" AND ap.name = "Auckland Airport"
RETURN fa.name AS accidentName;

MATCH (fa:FlightAccident)-[:destinedFor]->(a:Airport)
WHERE fa.name IN ["LOT Polish Airlines Flight 16", "Scandinavian Airlines System Flight 751"]
RETURN DISTINCT a.name AS destinationAirportName;
